-- Egypt: ES/DE/FR milestone translations (real translations replacing
-- the scaffolder's drafts/ stub). INSERT OR IGNORE, idempotent.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-law-2020', 'es', 'Ley de Procedimientos Tributarios Unificados y primera ola de facturación electrónica', 'La Ley N.º 206 de 2020 estableció la base legal del régimen de facturación electrónica de Egipto, otorgando a las firmas electrónicas el mismo valor legal que a las manuscritas. La primera ola de grandes contribuyentes registrados en el Centro de Grandes Contribuyentes de la ETA comenzó la facturación electrónica obligatoria en noviembre de 2020, abriendo un despliegue por fases que acabaría alcanzando a todas las empresas registradas a efectos de IVA.', '["Contexto histórico — no requiere acción"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-law-2020', 'de', 'Gesetz über einheitliche Steuerverfahren und erste E-Rechnungs-Welle', 'Das Gesetz Nr. 206 von 2020 schuf die Rechtsgrundlage für Ägyptens elektronisches Rechnungsstellungsregime und verlieh elektronischen Signaturen dieselbe Rechtswirkung wie handschriftlichen. Die erste Welle der beim Großsteuerzahler-Zentrum der ETA registrierten Unternehmen begann im November 2020 mit der verpflichtenden elektronischen Rechnungsstellung — der Auftakt eines stufenweisen Rollouts, der schließlich jedes umsatzsteuerregistrierte Unternehmen erreichen sollte.', '["Historischer Kontext — keine Maßnahme erforderlich"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-law-2020', 'fr', 'Loi sur les procédures fiscales unifiées et première vague de facturation électronique', 'La loi n° 206 de 2020 a établi la base légale du régime de facturation électronique de l''Égypte, conférant aux signatures électroniques la même valeur juridique qu''aux signatures manuscrites. La première vague de grands contribuables enregistrés auprès du Centre des grands contribuables de l''ETA a commencé la facturation électronique obligatoire en novembre 2020, ouvrant un déploiement par phases qui finirait par atteindre toutes les entreprises assujetties à la TVA.', '["Contexte historique — aucune action requise"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-einvoicing-all', 'es', 'Facturación electrónica B2B/B2G obligatoria para todas las empresas registradas a efectos de IVA (vigente desde abril de 2023)', 'Egipto opera un modelo de compensación centralizado: las facturas se emiten en JSON/XML estructurado, se firman digitalmente y se envían a la plataforma central de la Autoridad Tributaria Egipcia en tiempo real o casi real. El despliegue por fases que comenzó con los grandes contribuyentes en noviembre de 2020 alcanzó a todas las empresas registradas a efectos de IVA en abril de 2023, y desde julio de 2023 las facturas en papel ya no se reconocen para la deducción del IVA — solo las facturas electrónicas validadas por la ETA permiten recuperar el IVA soportado.', '["Asegúrese de que todas las entidades egipcias emitan a través de la plataforma de la ETA — las facturas en papel ya no permiten deducir el IVA", "Verifique que los certificados de firma digital y la codificación estandarizada de productos (GS1/EGS) estén implantados"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-einvoicing-all', 'de', 'B2B/B2G-E-Rechnungspflicht für alle umsatzsteuerregistrierten Unternehmen (in Kraft seit April 2023)', 'Ägypten betreibt ein zentralisiertes Clearance-Modell: Rechnungen werden in strukturiertem JSON/XML ausgestellt, digital signiert und in Echtzeit oder nahezu Echtzeit an die zentrale Plattform der ägyptischen Steuerbehörde übermittelt. Der im November 2020 mit den Großsteuerzahlern begonnene stufenweise Rollout erreichte bis April 2023 alle umsatzsteuerregistrierten Unternehmen, und seit Juli 2023 werden Papierrechnungen für den Vorsteuerabzug nicht mehr anerkannt — nur ETA-geprüfte elektronische Rechnungen berechtigen zum Vorsteuerabzug.', '["Stellen Sie sicher, dass alle ägyptischen Gesellschaften über die ETA-Plattform ausstellen — Papierrechnungen berechtigen nicht mehr zum Vorsteuerabzug", "Prüfen Sie, ob digitale Signaturzertifikate und die standardisierte Produktcodierung (GS1/EGS) vorhanden sind"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-einvoicing-all', 'fr', 'Facturation électronique B2B/B2G obligatoire pour toutes les entreprises assujetties à la TVA (en vigueur depuis avril 2023)', 'L''Égypte applique un modèle de validation préalable centralisé : les factures sont émises en JSON/XML structuré, signées numériquement et transmises à la plateforme centrale de l''autorité fiscale égyptienne en temps réel ou quasi réel. Le déploiement par phases, entamé avec les grands contribuables en novembre 2020, a atteint toutes les entreprises assujetties à la TVA en avril 2023, et depuis juillet 2023 les factures papier ne sont plus reconnues pour la déduction de la TVA — seules les factures électroniques validées par l''ETA permettent de récupérer la TVA d''amont.', '["Assurez-vous que toutes les entités égyptiennes émettent via la plateforme de l''ETA — les factures papier ne permettent plus de déduire la TVA", "Vérifiez que les certificats de signature numérique et le codage produit standardisé (GS1/EGS) sont en place"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-ereceipt-wave8', 'es', 'Sistema de recibos electrónicos: octava subfase del despliegue B2C (vigente desde septiembre de 2025)', 'La Decisión N.º 281 de 2025 incorporó a un grupo adicional de contribuyentes al sistema de recibos electrónicos de Egipto — la octava subfase de la segunda etapa del despliegue B2C. Las empresas obligadas deben integrar sus terminales punto de venta o sistemas ERP con la plataforma central de la ETA para que las transacciones con consumidores puedan verificarse en tiempo real, y pueden comprobar si están dentro del alcance a través de la página de consulta de la ETA.', '["Consulte la página de la ETA para confirmar si sus operaciones minoristas egipcias están dentro del alcance", "Integre los sistemas POS o ERP con la plataforma central de la ETA para la verificación de recibos en tiempo real"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-ereceipt-wave8', 'de', 'E-Beleg-System: achte Teilphase des B2C-Rollouts (in Kraft seit September 2025)', 'Der Beschluss Nr. 281 von 2025 nahm eine weitere Gruppe von Steuerpflichtigen in Ägyptens elektronisches Belegsystem auf — die achte Teilphase der zweiten Stufe des B2C-Rollouts. Verpflichtete Unternehmen müssen ihre Kassensysteme oder ERP-Systeme an die zentrale ETA-Plattform anbinden, damit Verbrauchertransaktionen in Echtzeit verifiziert werden können, und können über die Abfrageseite der ETA prüfen, ob sie in den Anwendungsbereich fallen.', '["Prüfen Sie über die ETA-Abfrageseite, ob Ihre ägyptischen Einzelhandelsaktivitäten in den Anwendungsbereich fallen", "Binden Sie POS- oder ERP-Systeme für die Echtzeit-Belegverifizierung an die zentrale ETA-Plattform an"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-ereceipt-wave8', 'fr', 'Système de reçus électroniques : huitième sous-phase du déploiement B2C (en vigueur depuis septembre 2025)', 'La décision n° 281 de 2025 a intégré un groupe supplémentaire de contribuables au système de reçus électroniques de l''Égypte — la huitième sous-phase de la deuxième étape du déploiement B2C. Les entreprises assujetties doivent connecter leurs terminaux de point de vente ou leurs systèmes ERP à la plateforme centrale de l''ETA afin que les transactions avec les consommateurs puissent être vérifiées en temps réel, et peuvent vérifier si elles entrent dans le champ d''application via la page de consultation de l''ETA.', '["Consultez la page de l''ETA pour confirmer si vos activités de détail égyptiennes entrent dans le champ d''application", "Connectez les systèmes POS ou ERP à la plateforme centrale de l''ETA pour la vérification des reçus en temps réel"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-enforcement-2026', 'es', 'Etapa de aplicación 2026: sanciones por presentación tardía y códigos QR en los recibos electrónicos impresos', 'Desde el 1 de enero de 2026, la ETA entró en la etapa de aplicación del despliegue iniciado en 2020. Ahora se aplica un régimen sancionador explícito a la presentación tardía de facturas y recibos electrónicos, cada recibo electrónico impreso debe mostrar un código QR que enlaza con el registro validado en el portal de la ETA, y un marco de aplicación escalonado puede llegar a suspender la capacidad de una empresa incumplidora para emitir facturas válidas. El incumplimiento también puede suponer la denegación de créditos de IVA soportado, la exclusión de contratos públicos y restricciones a la importación/exportación.', '["Audite la puntualidad de las presentaciones — los envíos tardíos de facturas y recibos electrónicos ahora conllevan sanciones explícitas", "Confirme que los recibos electrónicos impresos llevan el código QR que enlaza con el registro validado de la ETA"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-enforcement-2026', 'de', 'Durchsetzungsphase 2026: Strafen für verspätete Übermittlung und QR-Codes auf gedruckten E-Belegen', 'Zum 1. Januar 2026 trat die ETA in die Durchsetzungsphase des 2020 begonnenen Rollouts ein. Für die verspätete Übermittlung von E-Rechnungen und E-Belegen gilt nun ein explizites Sanktionsregime, jeder gedruckte E-Beleg muss einen QR-Code tragen, der auf den validierten Datensatz im ETA-Portal verweist, und ein gestuftes Durchsetzungssystem kann einem säumigen Unternehmen letztlich die Fähigkeit entziehen, gültige Rechnungen auszustellen. Verstöße können außerdem die Versagung des Vorsteuerabzugs, den Ausschluss von öffentlichen Aufträgen und Import-/Exportbeschränkungen nach sich ziehen.', '["Prüfen Sie die Pünktlichkeit Ihrer Übermittlungen — verspätete E-Rechnungs- und E-Beleg-Einreichungen ziehen nun explizite Strafen nach sich", "Stellen Sie sicher, dass gedruckte E-Belege den QR-Code mit Verweis auf den validierten ETA-Datensatz tragen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-enforcement-2026', 'fr', 'Phase d''application 2026 : pénalités pour transmission tardive et codes QR sur les reçus électroniques imprimés', 'Depuis le 1er janvier 2026, l''ETA est entrée dans la phase d''application du déploiement lancé en 2020. Un régime de pénalités explicite s''applique désormais à la transmission tardive des factures et reçus électroniques, chaque reçu électronique imprimé doit comporter un code QR renvoyant à l''enregistrement validé dans le portail de l''ETA, et un dispositif d''application à plusieurs niveaux peut aller jusqu''à suspendre la capacité d''une entreprise défaillante à émettre des factures valides. Le non-respect peut aussi entraîner le refus des crédits de TVA d''amont, l''exclusion des marchés publics et des restrictions à l''import/export.', '["Auditez la ponctualité de vos transmissions — les envois tardifs de factures et reçus électroniques entraînent désormais des pénalités explicites", "Confirmez que les reçus électroniques imprimés comportent le code QR renvoyant à l''enregistrement validé de l''ETA"]');

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-threshold-250k', 'es', 'Umbral de registro reducido a 250.000 EGP — el plazo de registro venció el 31 de marzo de 2026', 'Los requisitos de registro ampliados de la ETA redujeron el umbral de registro obligatorio en la facturación electrónica de 500.000 a 250.000 EGP de ingresos brutos anuales, incorporando al sistema a muchas pequeñas empresas antes exentas. Las empresas por encima del umbral debían registrarse ante la ETA antes del 31 de marzo de 2026; incumplir el plazo conlleva una multa de 20.000 EGP más una sanción diaria de 1.000 EGP. El umbral se mide sobre los ingresos brutos antes de gastos, y la ETA cruza automáticamente las declaraciones de IVA con las solicitudes de exención.', '["Si los ingresos brutos de 2025 de una entidad egipcia superaron los 250.000 EGP, verifique de inmediato su estado de registro ante la ETA — las sanciones diarias se acumulan", "Revise las filiales pequeñas y los acuerdos de autónomos que antes quedaban por debajo del antiguo umbral de 500.000 EGP"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-threshold-250k', 'de', 'Registrierungsschwelle auf 250.000 EGP gesenkt — Registrierungsfrist am 31. März 2026 abgelaufen', 'Die erweiterten Registrierungsanforderungen der ETA senkten die Schwelle für die verpflichtende E-Rechnungs-Registrierung von 500.000 auf 250.000 EGP Bruttojahresumsatz und ziehen damit viele zuvor befreite Kleinunternehmen in das System. Unternehmen oberhalb der Schwelle mussten sich bis zum 31. März 2026 bei der ETA registrieren; wer die Frist versäumt, zahlt eine Strafe von 20.000 EGP zuzüglich 1.000 EGP pro Tag. Maßgeblich ist der Bruttoumsatz vor Abzug der Kosten, und die ETA gleicht Umsatzsteuererklärungen automatisch mit Befreiungsanträgen ab.', '["Überschritt der Bruttoumsatz 2025 einer ägyptischen Gesellschaft 250.000 EGP, prüfen Sie umgehend deren ETA-Registrierungsstatus — die Tagesstrafen laufen auf", "Überprüfen Sie kleinere Tochtergesellschaften und Einzelunternehmer-Strukturen, die bisher unter der alten 500.000-EGP-Schwelle lagen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('eg-threshold-250k', 'fr', 'Seuil d''enregistrement abaissé à 250 000 EGP — la date limite d''enregistrement a expiré le 31 mars 2026', 'Les exigences d''enregistrement élargies de l''ETA ont abaissé le seuil d''enregistrement obligatoire à la facturation électronique de 500 000 à 250 000 EGP de chiffre d''affaires brut annuel, faisant entrer dans le système de nombreuses petites entreprises jusque-là exemptées. Les entreprises au-dessus du seuil devaient s''enregistrer auprès de l''ETA avant le 31 mars 2026 ; manquer l''échéance entraîne une amende de 20 000 EGP plus une pénalité quotidienne de 1 000 EGP. Le seuil se mesure sur le chiffre d''affaires brut avant charges, et l''ETA recoupe automatiquement les déclarations de TVA avec les demandes d''exemption.', '["Si le chiffre d''affaires brut 2025 d''une entité égyptienne a dépassé 250 000 EGP, vérifiez immédiatement son statut d''enregistrement auprès de l''ETA — les pénalités quotidiennes s''accumulent", "Passez en revue les petites filiales et les structures d''indépendants auparavant sous l''ancien seuil de 500 000 EGP"]');
